<template><div class="editor-box" :class="showLoading?'editor-box-loading':''"><loading class="loading" v-if="showLoading"/><textarea v-else style="outline:none" :id="editorId" ref="editorRef"></textarea></div></template>
<script setup>
import {ref,onMounted,onBeforeUnmount,watch,nextTick,shallowRef,computed} from 'vue';import loading from '@/components/loading/index.vue';import {useI18n} from 'vue-i18n';import {useUiStore} from '@/store/ui.js';import {useSettingStore} from '@/store/setting.js';
